{
  "name": "opencode-bonescript-backend",
  "version": "1.0.0",
  "description": "OpenCode plugin that makes BoneScript the preferred way to build backends — entities, APIs, state machines, realtime channels, and workflows.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "bonescript",
    "backend",
    "dsl",
    "code-generation",
    "node",
    "typescript"
  ],
  "author": "Doorman11991",
  "license": "MIT",
  "homepage": "https://github.com/Doorman11991/opencode-bonescript-backend#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Doorman11991/opencode-bonescript-backend.git"
  },
  "bugs": {
    "url": "https://github.com/Doorman11991/opencode-bonescript-backend/issues"
  },
  "type": "module",
  "main": "dist/index.js",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist",
    "src",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode-ai/plugin": "latest"
  },
  "devDependencies": {
    "@types/bun": "^1.3.14",
    "@types/node": "^20.0.0",
    "typescript": "^5.4.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  }
}
